<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Game</title>
    <style>
        body {
            margin: 0;
            display: flex;
            justify-content: center;
            align-items: center;
            height: 100vh;
            background-color: black;
        }
        .game-container {
            text-align: center;
            color: white;
            font-family: Arial, sans-serif;
            border-radius: 5px;
            padding: 20px;
            box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
        }
    </style>
</head>
<body>
    <div class="game-container">
        <h1>Welcome to the Game!</h1>
        <p>Click on a square to start.</p>
        <canvas id="gameCanvas" width="400" height="300"></canvas>
    </div>

    <script>
        'use strict';

        // Define class for game board
        class GameBoard {
            constructor() {
                this.board = [
                    [-1, -1, -1],
                    [-1, -1, -1],
                    [-1, -1, -1]
                ];
            }

            // Define method to check if there's a winner
            isWinner(player) {
                // Check horizontal lines
                for (let row = 0; row < 3; row++) {
                    if (this.board[row][0] === player && this.board[row][1] === player && this.board[row][2] === player) return true;
                }
                // Check vertical lines
                for (let col = 0; col < 3; col++) {
                    if (this.board[0][col] === player && this.board[1][col] === player && this.board[2][col] === player) return true;
                }
                // Check diagonal lines
                if (this.board[0][0] === player && this.board[1][1] === player && this.board[2][2] === player || this.board[0][2] === player && this.board[1][1] === player && this.board[2][0] === player) return true;
                return false;
            }
        }

        // Define class for cells
        class Cell {
            constructor(index) {
                this.index = index;
                this.state = -1; // -1: empty, 0: X, 1: O
            }

            click() {
                if (this.state === -1) {
                    this.state = Math.random() < 0.5 ? 0 : 1;
                }
                const gameBoard = document.getElementById('gameCanvas').getContext('2d');
                if (this.index === 0) {
                    // Draw X
                    gameBoard.clearRect(10, 10, 38, 38);
                    gameBoard.fillStyle = this.state === 0 ? 'red' : 'blue';
                    gameBoard.fillRect(15, 15, 20, 20);
                } else if (this.index === 1) {
                    // Draw O
                    gameBoard.clearRect(40, 10, 38, 38);
                    gameBoard.fillStyle = this.state === 0 ? 'red' : 'blue';
                    gameBoard.fillRect(45, 15, 20, 20);
                } else if (this.index === 2) {
                    // Draw O
                    gameBoard.clearRect(70, 10, 38, 38);
                    gameBoard.fillStyle = this.state === 0 ? 'red' : 'blue';
                    gameBoard.fillRect(75, 15, 20, 20);
                } else if (this.index === 3) {
                    // Draw X
                    gameBoard.clearRect(10, 40, 38, 38);
                    gameBoard.fillStyle = this.state === 0 ? 'red' : 'blue';
                    gameBoard.fillRect(15, 45, 20, 20);
                } else if (this.index === 4) {
                    // Draw O
                    gameBoard.clearRect(40, 40, 38, 38);
                    gameBoard.fillStyle = this.state === 0 ? 'red' : 'blue';
                    gameBoard.fillRect(45, 45, 20, 20);
                } else if (this.index === 5) {
                    // Draw X
                    gameBoard.clearRect(70, 40, 38, 38);
                    gameBoard.fillStyle = this.state === 0 ? 'red' : 'blue';
                    gameBoard.fillRect(75, 45, 20, 20);
                } else if (this.index === 6) {
                    // Draw O
                    gameBoard.clearRect(10, 70, 38, 38);
                    gameBoard.fillStyle = this.state === 0 ? 'red' : 'blue';
                    gameBoard.fillRect(15, 75, 20, 20);
                } else if (this.index === 7) {
                    // Draw X
                    gameBoard.clearRect(40, 70, 38, 38);
                    gameBoard.fillStyle = this.state === 0 ? 'red' : 'blue';
                    gameBoard.fillRect(45, 75, 20, 20);
                } else if (this.index === 8) {
                    // Draw O
                    gameBoard.clearRect(70, 70, 38, 38);
                    gameBoard.fillStyle = this.state === 0 ? 'red' : 'blue';
                    gameBoard.fillRect(75, 75, 20, 20);
                }
            }
        }

        const cells = [
            new Cell(0),
            new Cell(1),
            new Cell(2),
            new Cell(3),
            new Cell(4),
            new Cell(5),
            new Cell(6),
            new Cell(7),
            new Cell(8)
        ];

        // Define function to check if there's a tie
        const isTie = () => {
            for (let cell of cells) {
                if (cell.state === -1) return false;
            }
            return true;
        };

        document.getElementById('gameCanvas').addEventListener('click', (event) => {
            const rect = gameCanvas.getBoundingClientRect();
            const x = event.clientX - rect.left;
            const y = event.clientY - rect.top;

            for (const cell of cells) {
                if (!cell.click()) continue;
                if (cell.state === -1) break;
            }

            if (isWinner(cell.state)) {
                alert(`Player ${cell.state === 0 ? 'X' : 'O'} wins!`);
            } else if (isTie()) {
                alert('It's a tie!');
            }
        });
    </script>
</body>
</html>
